with cleaned as (select id, full_name, manager_id, job_title, hire_date, is_remote, level, cast(salary as int) as salary_int from employees where level is not null) select date_trunc('month', hire_date) as activity_month, level, sort_array(collect_set(level)) as level_list, count(distinct id) as distinct_ids, sort_array(collect_set(job_title)) as job_title_list, dense_rank() over (partition by date_trunc('month', hire_date) order by count(distinct id) desc) as distinct_ids_dense_rank from cleaned group by 1, 2 order by level asc nulls first
